def scalar_secant(z,cap,domain):
 z=np.asarray(z,dtype=np.float32);cap=np.float32(cap);h=np.sqrt(np.float32(np.finfo(np.float32).eps))*(np.float32(1)+abs(z)+cap)
 if domain=='positive':
  dz=np.clip((np.float32(1)+z/h)*np.float32(.5),np.float32(0),np.float32(1));dc=np.zeros_like(z)
 else:
  above=np.clip((np.float32(1)+(z-cap)/h)*np.float32(.5),np.float32(0),np.float32(1));below=np.clip((np.float32(1)+(-cap-z)/h)*np.float32(.5),np.float32(0),np.float32(1));dz=np.clip(np.float32(1)-above-below,np.float32(0),np.float32(1));dc=above-below
 assert dz.dtype==dc.dtype==np.float32 and np.all((dz>=0)&(dz<=1));return np.diag(dz),dc
controls=[]
for domain,z,cap,expected in [('positive',-1,0,0),('positive',0,0,.5),('positive',1,0,1),('box',-2,1,0),('box',-1,1,.5),('box',0,1,1),('box',1,1,.5),('box',2,1,0),('box',0,0,0)]:
 dz,_=scalar_secant(np.array([z],dtype=np.float32),cap,domain);error=abs(float(dz[0,0])-expected);assert error<=1e-7;controls.append(dict(domain=domain,z=z,cap=cap,error=error))
(p/'secant-controls.json').write_text(json.dumps(dict(cases=controls),indent=2))

